window.CALCULATORS=window.CALCULATORS||[];window.CALCULATORS.push({id:"home-loan-eligibility",slug:"home-loan-eligibility-calculator",title:"Home Loan Eligibility Calculator",category:"loan",short:"Estimate a home-loan amount from income and EMI capacity.",desc:"Use an assumed FOIR, existing EMIs, rate and tenure to estimate indicative eligibility.",article:{formula:"Eligible EMI = monthly income × FOIR − existing EMIs.",exampleInputs:{},faqs:[{q:"What is FOIR?",a:"It is a lender-style affordability ratio; actual thresholds differ by lender."},{q:"Is this an approval?",a:"No. Credit, age, employment, property valuation and lender policy can change eligibility."},{q:"Why subtract existing EMIs?",a:"Existing obligations reduce monthly capacity for a new loan."}]},fields:[{id:"income",label:"Monthly income",type:"number",default:150000,min:0,max:1000000000000,step:1},{id:"foir",label:"Assumed FOIR",type:"number",default:50,min:10,max:100,step:0.1},{id:"existing",label:"Existing monthly EMIs",type:"number",default:15000,min:0,max:1000000000000,step:1},{id:"rate",label:"Annual interest rate",type:"number",default:8.5,min:0,max:100,step:0.1},{id:"years",label:"Loan term",type:"number",default:20,min:1,max:100,step:0.1}],compute(v){const capacity=Math.max(v.income,0)*Math.max(v.foir,0)/100-Math.max(v.existing,0),n=Math.max(1,Math.round(v.years*12)),r=Math.max(v.rate,0)/1200,loan=capacity<=0?0:r===0?capacity*n:capacity*((1+r)**n-1)/(r*(1+r)**n);return[{label:'Indicative EMI capacity',value:Math.max(capacity,0),format:'currency'},{label:'Indicative eligible loan',value:Math.max(loan,0),format:'currency',emphasis:'neutral'}];}});
